-- Les 257 fiches produits actives en japonais et en chinois simplifié
-- (18/11, Alexandra : « les descriptions des affiches en japonais est en
-- anglais c'est pas bon ») : nom court, description, et titre et description
-- Google quand la fiche en a. Même méthode que la 0094 : texte source lu sur
-- memoryline.fr le 18/11 ; rien n'est écrasé ; une fiche renommée ou dont la
-- description française a changé depuis est laissée telle quelle.
UPDATE "product" x
SET "translations" = coalesce(x."translations", '{}'::jsonb) || (
    SELECT jsonb_object_agg(l.key, l.value || coalesce((
      SELECT jsonb_object_agg(e.key, e.value)
      FROM jsonb_each(CASE WHEN jsonb_typeof(x."translations" -> l.key) = 'object' THEN x."translations" -> l.key ELSE '{}'::jsonb END) e
      WHERE jsonb_typeof(e.value) = 'string' AND btrim(e.value #>> '{}') <> ''
    ), '{}'::jsonb))
    FROM jsonb_each(t.trad) l
  )
FROM (VALUES
  ('velo-course-affiche-personnalisee', 'VÉLO Course - Affiche personnalisée', 'b5f430519e0e0eba057db9e30725eddf', '{"ja":{"name":"VÉLO 自転車レース","description":"VÉLO 自転車レースのパーソナライズポスターをご紹介します。自転車レースの雰囲気に着想を得たイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、テキストをお好みに変更して、あなたらしい思い出を残せます。誕生日やクリスマス、特別な日のオリジナルギフトにぴったりで、自転車とスポーツ好きの方々に特に喜ばれています。リビングや寝室、オフィスに飾ったり、贈ったりできるパーソナライズポスターです。VÉLO 自転車レースのパーソナライズポスター：オーダーメイドのポスター、旅の思い出、ウォールデコ、そしてパーソナライズギフト。","seoTitle":"VÉLO 自転車レース - パーソナライズポスター","seoDescription":"VÉLO 自転車レースのパーソナライズポスター。大切な人と作る世界にひとつの思い出。壁飾りやギフトに。"},"zh":{"name":"VÉLO 自行车赛","description":"为您推荐VÉLO 自行车赛个性化海报，这是一幅受自行车赛的氛围启发的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属纪念。这款设计是生日、圣诞节或特别场合的创意礼物，尤其受热爱自行车和运动的人喜爱。一幅个性化海报，可作为礼物赠送，也可摆放在客厅、卧室或办公室。VÉLO 自行车赛个性化海报：定制海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"VÉLO 自行车赛 - 个性化海报","seoDescription":"VÉLO 自行车赛个性化海报：与亲友打造专属海报。独特纪念、墙面装饰、圣诞生日礼物。"}}'::jsonb),
  ('turckheim-affiche-personnalisee', 'TURCKHEIM - Affiche personnalisée', '73da98da8d46fdec6121f8074a2b601a', '{"ja":{"name":"TURCKHEIM","description":"TURCKHEIM パーソナライズポスターのご紹介です。Turckheimとアルザスの街並みに着想を得たイラストポスターです。キャラクターとして、ご家族、ご友人、カップル、ペットを加え、テキストを変更して、あなたらしい思い出に仕上げられます。このデザインは、誕生日やクリスマス、特別な日のオリジナルギフトに最適で、特にブドウ畑の村々がお好きな方に喜ばれています。リビング、寝室、オフィスに飾ったり、贈り物にしたりできるパーソナライズポスターです。TURCKHEIM パーソナライズポスター:パーソナライズポスター、旅の思い出、ウォールデコ、パーソナライズギフト。","seoTitle":"TURCKHEIM - パーソナライズポスター","seoDescription":"TURCKHEIM パーソナライズポスター:ご家族やご友人と作るアルザスの思い出ポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"TURCKHEIM","description":"TURCKHEIM 个性化海报，灵感来自Turckheim及其阿尔萨斯街巷的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的纪念。这款设计是生日、圣诞节或特殊场合的创意礼物，尤其受到热爱葡萄园村庄的人们青睐。可放置在客厅、卧室或办公室，也适合作为礼物赠送。TURCKHEIM 个性化海报：个性化海报、旅行纪念、墙面装饰和个性化礼物。","seoTitle":"TURCKHEIM - 个性化海报","seoDescription":"TURCKHEIM 个性化海报：与亲友一起打造阿尔萨斯纪念海报，适合圣诞节或生日送礼。"}}'::jsonb),
  ('suisse-rosenlaui-valley-affiche-personnalisee', 'SUISSE Rosenlaui Valley - Affiche personnalisée', '66349250db814460072fed0550c88f44', '{"ja":{"name":"スイス Rosenlaui Valley","description":"スイス Rosenlaui Valleyのパーソナライズポスターをご紹介します。スイスのローゼンラウイ渓谷をモチーフにしたイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、文字をアレンジして、自分らしい思い出を残してください。このデザインは、誕生日やクリスマス、特別な日の個性的なギフトにぴったりで、特にアルプスの風景がお好きな方に喜ばれています。贈り物にも、リビングや寝室、オフィスの装飾にもお使いいただけるパーソナライズポスターです。パーソナライズポスター スイス Rosenlaui Valley：オーダーメイドのポスター、旅の思い出、ウォールデコレーション、そしてパーソナライズギフト。","seoTitle":"スイス Rosenlaui Valley - パーソナライズポスター","seoDescription":"パーソナライズポスター スイス Rosenlaui Valley：大切な人と作るポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"瑞士 Rosenlaui Valley","description":"探索个性化海报瑞士 Rosenlaui Valley，这是一幅以瑞士的罗森劳依山谷为灵感的插画海报。您可以添加代表家人、朋友、伴侣或宠物的人物，再自定义文字，留下属于您的专属回忆。这幅作品是生日、圣诞节或特别场合的创意礼物，尤其受到热爱阿尔卑斯风光的人的喜爱。这款个性化海报既可送礼，也可装饰客厅、卧室或办公室。个性化海报瑞士 Rosenlaui Valley：定制海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"瑞士 Rosenlaui Valley - 个性化海报","seoDescription":"个性化海报瑞士 Rosenlaui Valley：与亲友一起定制海报。圣诞节或生日礼物之选。"}}'::jsonb),
  ('tennis-match-affiche-personnalisee', 'TENNIS Match - Affiche personnalisée', '4dfb91b9b13f54124e9dd528d5871cf9', '{"ja":{"name":"テニス 試合","description":"テニス 試合 パーソナライズポスターのご紹介です。テニスの試合の躍動感に着想を得たイラストポスターです。キャラクターとして、ご家族、ご友人、カップル、ペットを加え、テキストを変更して、あなたらしい思い出に仕上げられます。このデザインは、誕生日やクリスマス、特別な日のオリジナルギフトに最適で、特にテニスをする方やテニス愛好家に喜ばれています。リビング、寝室、オフィスに飾ったり、贈り物にしたりできるパーソナライズポスターです。テニス 試合 パーソナライズポスター:パーソナライズポスター、旅の思い出、ウォールデコ、パーソナライズギフト。","seoTitle":"テニス 試合 - パーソナライズポスター","seoDescription":"テニス 試合 パーソナライズポスター:ご家族やご友人と作るアルザスの思い出ポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"网球 比赛","description":"网球 比赛 个性化海报，灵感来自网球比赛活力的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的纪念。这款设计是生日、圣诞节或特殊场合的创意礼物，尤其受到网球运动员和网球爱好者青睐。可放置在客厅、卧室或办公室，也适合作为礼物赠送。网球 比赛 个性化海报：个性化海报、旅行纪念、墙面装饰和个性化礼物。","seoTitle":"网球 比赛 - 个性化海报","seoDescription":"网球 比赛 个性化海报：与亲友一起打造阿尔萨斯纪念海报，适合圣诞节或生日送礼。"}}'::jsonb),
  ('strasbourg-ponts-couverts-sunset-affiche-personnalisee', 'STRASBOURG Ponts Couverts SUNSET - Affiche personnalisée', 'ca99413da8678adcb6589a42e393c3af', '{"ja":{"name":"STRASBOURG Ponts Couverts サンセット","description":"STRASBOURG Ponts Couverts サンセットのパーソナライズポスターをご紹介します。夕暮れのストラスブールのPonts Couverts（屋根付き橋）にインスパイアされたイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、テキストをお好みに変えて、あなたらしい思い出を残しましょう。誕生日、クリスマス、特別な日のオリジナルギフトにぴったりで、ストラスブールの夕暮れの光を愛する方に特に喜ばれるデザインです。贈り物としても、リビングや寝室、オフィスのインテリアとしても楽しめるパーソナライズポスターです。STRASBOURG Ponts Couverts サンセットのパーソナライズポスター：オーダーメイドポスター、旅の思い出、ウォールデコ、パーソナライズギフト。","seoTitle":"STRASBOURG Ponts Couverts サンセット","seoDescription":"STRASBOURG Ponts Couverts サンセットのパーソナライズポスター。大切な方と作るオリジナルポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"STRASBOURG Ponts Couverts 日落","description":"为您推荐STRASBOURG Ponts Couverts 日落个性化海报，一幅以日落时分的斯特拉斯堡有盖桥（Ponts Couverts）为灵感的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属回忆。这幅作品是生日、圣诞节或特殊场合的原创礼物之选，尤其受到钟爱斯特拉斯堡暮色灯光的人的喜爱。既可作为礼物赠送，也可装饰客厅、卧室或办公室。STRASBOURG Ponts Couverts 日落个性化海报：定制海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"STRASBOURG Ponts Couverts 日落 海报","seoDescription":"STRASBOURG Ponts Couverts 日落个性化海报：与亲友一起定制专属海报。圣诞节或生日的礼物之选。"}}'::jsonb),
  ('strasbourg-ponts-couverts-affiche-personnalisee', 'STRASBOURG Ponts Couverts - Affiche personnalisée', 'e512c689d3cdf9d80389ea971453952b', '{"ja":{"name":"STRASBOURG Ponts Couverts","description":"STRASBOURG Ponts Couvertsのパーソナライズポスターをご紹介します。ストラスブールのPonts Couverts（屋根付き橋）にインスパイアされたイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、テキストをお好みに変えて、あなたらしい思い出を残しましょう。誕生日、クリスマス、特別な日のオリジナルギフトにぴったりで、プティット・フランスとその運河がお好きな方に特に喜ばれるデザインです。贈り物としても、リビングや寝室、オフィスのインテリアとしても楽しめるパーソナライズポスターです。STRASBOURG Ponts Couvertsのパーソナライズポスター：オーダーメイドポスター、旅の思い出、ウォールデコ、パーソナライズギフト。","seoTitle":"STRASBOURG Ponts Couverts ポスター","seoDescription":"STRASBOURG Ponts Couvertsのパーソナライズポスター。大切な方と作るオリジナルポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"STRASBOURG Ponts Couverts","description":"为您推荐STRASBOURG Ponts Couverts个性化海报，一幅以斯特拉斯堡有盖桥（Ponts Couverts）为灵感的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属回忆。这幅作品是生日、圣诞节或特殊场合的原创礼物之选，尤其受到钟爱小法兰西区及其运河的人的喜爱。既可作为礼物赠送，也可装饰客厅、卧室或办公室。STRASBOURG Ponts Couverts个性化海报：定制海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"STRASBOURG Ponts Couverts 海报","seoDescription":"STRASBOURG Ponts Couverts个性化海报：与亲友一起定制专属海报。圣诞节或生日的礼物之选。"}}'::jsonb),
  ('suisse-affiche-personnalisee', 'SUISSE - Affiche personnalisée', '046ed24b6f740f9bfa407334a5b4a86b', '{"ja":{"name":"スイス","description":"スイスのパーソナライズポスターをご紹介します。スイスを象徴する風景にインスピレーションを得たイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、テキストをカスタマイズして、あなたらしい思い出を残しましょう。このビジュアルは、誕生日、クリスマス、特別な日のオリジナリティあふれるギフトにぴったりで、山と旅を愛する方々に特に喜ばれています。プレゼントにも、リビング、寝室、オフィスの装飾にもお使いいただけるパーソナライズポスターです。パーソナライズポスタースイス：パーソナライズポスター、旅の思い出、壁飾り、オリジナルギフト。","seoTitle":"スイス - パーソナライズポスター","seoDescription":"スイス：大切な人と作るポスター。唯一の思い出、壁飾り、クリスマスや誕生日のギフトに。"},"zh":{"name":"瑞士","description":"为您介绍个性化海报瑞士，这是一款灵感来自瑞士的标志性风光的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属回忆。这款作品是生日、圣诞节或特别场合的创意礼物，尤其深受热爱山川与旅行的人士喜爱。这是一幅适合赠送或摆放在客厅、卧室或办公室的个性化海报。个性化海报瑞士：个性化海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"瑞士 - 个性化海报","seoDescription":"瑞士：与亲友一起定制海报。独一无二的回忆、墙面装饰，圣诞节或生日礼物的好选择。"}}'::jsonb),
  ('strasbourg-neige-affiche-personnalisee', 'STRASBOURG Neige - Affiche personnalisée', 'd3beb983808f38107d1a775f1f6be33c', '{"ja":{"name":"STRASBOURG 雪景色","description":"STRASBOURG 雪景色のパーソナライズポスターのご紹介です。雪化粧したストラスブールに着想を得たイラストポスターです。ご家族、友人、カップル、ペットを表すキャラクターを追加し、文字もお好みに変更して、あなたらしい思い出を残しましょう。誕生日、クリスマス、特別な日のオリジナルギフトに最適で、冬のアルザス滞在がお好きな方々に特に喜ばれます。リビングや寝室、オフィスに飾ったり、贈り物にしたりできるパーソナライズポスターです。STRASBOURG 雪景色 パーソナライズポスター：オーダーメイドポスター、旅の思い出、壁面装飾、パーソナライズギフト。","seoTitle":"STRASBOURG 雪景色 | パーソナライズポスター","seoDescription":"STRASBOURG 雪景色のパーソナライズポスター。大切な人と作る世界にひとつの思い出。壁面装飾やクリスマス・誕生日のギフトに。"},"zh":{"name":"STRASBOURG 雪景","description":"为您推荐个性化海报“STRASBOURG 雪景”，这是一幅受雪中斯特拉斯堡启发的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属纪念。这幅画面是生日、圣诞节或特别场合的原创礼品佳选，尤其深受喜爱冬季阿尔萨斯之旅的朋友喜爱。这款个性化海报可作为礼物赠送，也可装饰客厅、卧室或办公室。STRASBOURG 雪景 个性化海报：定制海报、旅行纪念、墙面装饰与个性化礼品。","seoTitle":"STRASBOURG 雪景 | 个性化海报","seoDescription":"STRASBOURG 雪景个性化海报：与亲友一起创作。独特纪念、墙面装饰，圣诞节、生日礼物创意。"}}'::jsonb),
  ('strasbourg-maison-kammerzell-affiche-personnalisee', 'STRASBOURG Maison Kammerzell - Affiche personnalisée', 'b17b06f30e50422fd535c1795a896cd6', '{"ja":{"name":"STRASBOURG メゾン・カメルゼル","description":"STRASBOURG メゾン・カメルゼルのパーソナライズポスターをご紹介します。ストラスブールの有名なカメルゼルの家にインスピレーションを得たイラストポスターです。ご家族、ご友人、カップル、ペットを表すキャラクターを追加し、テキストをカスタマイズして、あなたらしい思い出を残しましょう。このビジュアルは、誕生日、クリスマス、特別な日のオリジナリティあふれるギフトにぴったりで、アルザスの歴史ある木組みのファサードを愛する方々に特に喜ばれています。プレゼントにも、リビング、寝室、オフィスの装飾にもお使いいただけるパーソナライズポスターです。パーソナライズポスターSTRASBOURG メゾン・カメルゼル：パーソナライズポスター、旅の思い出、壁飾り、オリジナルギフト。","seoTitle":"STRASBOURG メゾン・カメルゼル - パーソナライズポスター","seoDescription":"STRASBOURG メゾン・カメルゼル：大切な人と作れるパーソナライズポスター。クリスマスや誕生日のギフトに。"},"zh":{"name":"STRASBOURG 卡梅尔泽尔之家","description":"为您介绍个性化海报STRASBOURG 卡梅尔泽尔之家，这是一款灵感来自斯特拉斯堡著名的卡梅尔泽尔之家的插画海报。您可以添加代表家人、朋友、情侣或宠物的人物，并自定义文字，留下属于您的专属回忆。这款作品是生日、圣诞节或特别场合的创意礼物，尤其深受热爱阿尔萨斯历史建筑立面的人士喜爱。这是一幅适合赠送或摆放在客厅、卧室或办公室的个性化海报。个性化海报STRASBOURG 卡梅尔泽尔之家：个性化海报、旅行纪念、墙面装饰与个性化礼物。","seoTitle":"STRASBOURG 卡梅尔泽尔之家 - 个性化海报","seoDescription":"STRASBOURG 卡梅尔泽尔之家：与亲友一起定制的个性化海报。圣诞节或生日礼物的好选择。"}}'::jsonb),
